"use client"

import * as React from "react"
import { AlertCircle, FileQuestion, RefreshCw } from "lucide-react"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import { FileViewer } from "@/components/ui/file-viewer"
import { Spinner } from "@/components/ui/spinner"

import {
  FileSystemOpenPreview,
  useFileSystemOpenPreview,
} from "./file-system-open-preview-dialog"
import {
  FileSystemBrowser,
  FileSystemHeader,
  FileSystemSelection,
  useFileSystemBrowser,
  useFileSystemHeader,
  useFileSystemSelectedItem,
  useFileSystemSelectedSource,
  useFileSystemSelection,
  type FileSystemSelectionRenderState,
} from "./file-system-parts"
import { FileSystemProvider, useFileSystem } from "./file-system-provider"
import { FileSystemThumbnail } from "./file-system-thumbnail"
import type {
  FileSystemEntry,
  FileSystemFileItem,
  FileSystemProps,
} from "./file-system-types"
import {
  ViewerBody,
  ViewerHeader,
  ViewerRoot,
  ViewerSidebar,
  ViewerSurface,
} from "./viewer"

export {
  FileSystemOpenPreview,
  FileSystemProvider,
  FileSystemBrowser,
  FileSystemHeader,
  FileSystemSelection,
  useFileSystem,
  useFileSystemBrowser,
  useFileSystemHeader,
  useFileSystemOpenPreview,
  useFileSystemSelectedItem,
  useFileSystemSelectedSource,
  useFileSystemSelection,
}

export type {
  FileSystemFileItem,
  FileSystemFolderItem,
  FileSystemItem,
  FileSystemLoadChildrenArgs,
  FileSystemLoadChildrenResult,
  FileSystemProps,
  FileSystemQueryState,
  FileSystemResolveSourceArgs,
  FileSystemView,
} from "./file-system-types"
export type { FileSystemProviderProps } from "./file-system-provider"
export type {
  FileSystemBrowserPartState,
  FileSystemHeaderState,
  FileSystemSelectionRenderState,
  FileSystemSelectionState,
} from "./file-system-parts"

export function FileSystem({ className, ...providerProps }: FileSystemProps) {
  return (
    <FileSystemProvider {...providerProps}>
      <div data-slot="file-system">
        <ViewerRoot
          data-viewer="file-system"
          bare
          defaultOpen
          className={cn(
            "h-[640px] rounded-md border bg-background text-foreground",
            className
          )}
        >
          <ViewerHeader className="flex flex-col">
            <FileSystemHeader />
          </ViewerHeader>
          <ViewerBody>
            <ViewerSidebar
              aria-label="Files"
              width="min(22rem, 85vw)"
              className="flex min-w-0 flex-col border-r"
            >
              <FileSystemBrowser />
            </ViewerSidebar>
            <ViewerSurface className="bg-background">
              <FileSystemSelection>
                {(selection) => (
                  <FileSystemDefaultSelectionContent selection={selection} />
                )}
              </FileSystemSelection>
            </ViewerSurface>
          </ViewerBody>
          <FileSystemOpenPreview />
        </ViewerRoot>
      </div>
    </FileSystemProvider>
  )
}

function FileSystemDefaultSelectionContent({
  selection,
}: {
  selection: FileSystemSelectionRenderState
}) {
  const {
    entry,
    renderFileActions,
    renderMetadata,
    resolveSource,
    retry,
    sourceState,
  } = selection

  return (
    <div
      data-slot="file-system-default-selection"
      className="flex size-full min-h-0 min-w-0 flex-col overflow-hidden bg-muted/20"
    >
      <div className="flex min-h-0 flex-1 flex-col">
        <div className="flex min-h-0 flex-1 items-center justify-center overflow-hidden bg-background">
          {!entry ? (
            <FileSystemDefaultSelectionMessage
              title="No file selected"
              description="Select a file to preview it."
            />
          ) : entry.kind === "folder" ? (
            <FileSystemDefaultSelectionMessage
              title={entry.name}
              description="Folders show their contents in the browser."
            />
          ) : sourceState.status === "loading" ? (
            <div className="flex items-center gap-2 text-sm text-muted-foreground">
              <Spinner className="size-4" />
              Loading preview
            </div>
          ) : sourceState.status === "error" ? (
            <FileSystemDefaultSelectionMessage
              icon={<AlertCircle className="size-5" aria-hidden />}
              title="Couldn't load preview"
              description={sourceState.error}
              action={
                <Button size="sm" variant="outline" onClick={retry}>
                  <RefreshCw className="size-3.5" aria-hidden />
                  Retry
                </Button>
              }
            />
          ) : sourceState.status === "ready" ? (
            <FileViewer
              source={sourceState.source}
              bare
              className="size-full min-h-0"
            />
          ) : sourceState.status === "unavailable" ? (
            <FileSystemDefaultSelectionMessage
              icon={<FileQuestion className="size-5" aria-hidden />}
              title="Preview unavailable"
              description="This file does not have a resolved source."
            />
          ) : null}
        </div>
        {entry ? (
          <FileSystemDefaultSelectionFooter
            entry={entry}
            renderFileActions={renderFileActions}
            renderMetadata={renderMetadata}
            resolveFileSource={resolveSource}
          />
        ) : null}
      </div>
    </div>
  )
}

function FileSystemDefaultSelectionFooter({
  entry,
  renderFileActions,
  renderMetadata,
  resolveFileSource,
}: {
  entry: FileSystemEntry
  renderFileActions?: (file: FileSystemFileItem) => React.ReactNode
  renderMetadata?: (item: FileSystemEntry) => React.ReactNode
  resolveFileSource: FileSystemSelectionRenderState["resolveSource"]
}) {
  const file = entry.kind === "file" ? entry : null

  return (
    <div className="shrink-0 border-t bg-background p-3">
      <div className="flex items-start gap-3">
        {file ? (
          <FileSystemThumbnail
            file={file}
            resolveFileSource={resolveFileSource}
            className="w-12 shrink-0"
          />
        ) : (
          <div className="flex size-12 shrink-0 items-center justify-center rounded-sm bg-muted text-lg">
            {folderInitial(entry.name)}
          </div>
        )}
        <div className="min-w-0 flex-1">
          <div className="text-sm font-medium break-words">{entry.name}</div>
          <div className="mt-0.5 truncate text-xs text-muted-foreground">
            {entry.path}
          </div>
        </div>
        {file ? renderFileActions?.(file) : null}
      </div>
      {renderMetadata ? (
        <div className="mt-3">{renderMetadata(entry)}</div>
      ) : null}
    </div>
  )
}

function FileSystemDefaultSelectionMessage({
  action,
  description,
  icon,
  title,
}: {
  action?: React.ReactNode
  description: string
  icon?: React.ReactNode
  title: string
}) {
  return (
    <div className="flex max-w-xs flex-col items-center gap-2 px-6 text-center">
      {icon ? <div className="text-muted-foreground">{icon}</div> : null}
      <div className="text-sm font-medium">{title}</div>
      <div className="text-xs text-muted-foreground">{description}</div>
      {action ? <div className="pt-1">{action}</div> : null}
    </div>
  )
}

function folderInitial(name: string) {
  return name.trim().charAt(0).toUpperCase() || "/"
}

"use client"

import * as React from "react"

import { useFileSystemKernelRuntime } from "./file-system-kernel-runtime"
import {
  selectFileSystemBrowserState,
  selectFileSystemSelectionState,
} from "./file-system-kernel-selectors"
import {
  useFileSystemOpenPreviewController,
  type FileSystemOpenPreviewController,
} from "./file-system-open-preview-state"
import { useFileSystemSourceController } from "./file-system-source-controller"
import type { FileSystemProps } from "./file-system-types"

export type FileSystemProviderProps = Omit<FileSystemProps, "className"> & {
  children: React.ReactNode
}

export type FileSystemRenderers = {
  renderFileActions?: FileSystemProps["renderFileActions"]
  renderMetadata?: FileSystemProps["renderMetadata"]
}

export type FileSystemCompositionState = {
  openPreview: FileSystemOpenPreviewController
  renderers: FileSystemRenderers
  title: string
}

export type FileSystemContextValue = {
  browser: ReturnType<typeof selectFileSystemBrowserState>
  selection: ReturnType<typeof selectFileSystemSelectionState>
} & FileSystemCompositionState

const FileSystemContext = React.createContext<FileSystemContextValue | null>(
  null
)

export function useFileSystem() {
  const context = React.useContext(FileSystemContext)
  if (!context) {
    throw new Error("useFileSystem must be used within FileSystemProvider.")
  }
  return context
}

export function FileSystemProvider({
  items,
  children,
  defaultPath,
  defaultQuery,
  defaultSelectedPath,
  defaultView = "list",
  loadChildren,
  onPathChange,
  onQueryChange,
  onFileOpen,
  onSelectionChange,
  onViewChange,
  path,
  query,
  renderFileActions,
  renderMetadata,
  resolveSource,
  selectedPath,
  title = "Files",
  view,
}: FileSystemProviderProps) {
  const source = useFileSystemSourceController({ items, resolveSource })
  const openPreview = useFileSystemOpenPreviewController({
    onFileOpen,
    resolveFileSource: source.resolveFileSource,
  })
  const kernel = useFileSystemKernelRuntime({
    defaultPath,
    defaultQuery,
    defaultSelectedPath,
    defaultView,
    items,
    loadChildren,
    onFileCommand: openPreview.open,
    onPathChange,
    onQueryChange,
    onSelectionChange,
    onViewChange,
    path,
    query,
    selectedPath,
    view,
  })
  const browser = React.useMemo(
    () =>
      selectFileSystemBrowserState({
        dispatch: kernel.dispatch,
        ensureChildren: kernel.ensureChildren,
        getState: kernel.getState,
        state: kernel.state,
      }),
    [kernel.dispatch, kernel.ensureChildren, kernel.getState, kernel.state]
  )
  const selection = React.useMemo(
    () =>
      selectFileSystemSelectionState({
        resolveSource: source.resolveFileSource,
        state: kernel.state,
      }),
    [kernel.state, source.resolveFileSource]
  )
  const renderers = React.useMemo<FileSystemRenderers>(
    () => ({ renderFileActions, renderMetadata }),
    [renderFileActions, renderMetadata]
  )
  const value = React.useMemo<FileSystemContextValue>(
    () => ({
      browser,
      selection,
      openPreview,
      renderers,
      title,
    }),
    [browser, openPreview, renderers, selection, title]
  )

  return (
    <FileSystemContext.Provider value={value}>
      {children}
    </FileSystemContext.Provider>
  )
}

"use client"

import * as React from "react"

import {
  createFileSystemBrowserController,
  type FileSystemBrowserController,
} from "./file-system-browser-controller"
import type {
  FileSystemHeaderState,
  FileSystemSelectionState as FileSystemSelectionDomainState,
} from "./file-system-browser-state"
import { createFileSystemHeaderState } from "./file-system-browser-state"
import { FileSystemColumnsView } from "./file-system-columns-view"
import {
  FileSystemCommandBar,
  FileSystemStatusBar,
  FileSystemToolbar,
} from "./file-system-controls"
import { FileSystemGridView } from "./file-system-grid-view"
import { FileSystemListView } from "./file-system-list-view"
import { useFileSystem } from "./file-system-provider"
import {
  useFileSystemSelectionSourceTask,
  type FileSystemSelectionSourceTask,
} from "./file-system-selection-source-task"
import type {
  FileSystemEntry,
  FileSystemFileEntry,
  FileSystemProps,
} from "./file-system-types"

export type FileSystemBrowserPartState = FileSystemBrowserController

export type { FileSystemHeaderState } from "./file-system-browser-state"

export type FileSystemSelectionState = FileSystemSelectionDomainState & {
  renderFileActions?: FileSystemProps["renderFileActions"]
  renderMetadata?: FileSystemProps["renderMetadata"]
}

export type FileSystemSelectionRenderState = FileSystemSelectionState & {
  file: FileSystemFileEntry | null
  retry: () => void
  source: FileSystemSelectionSourceTask["source"]
  sourceState: FileSystemSelectionSourceTask
}

export function useFileSystemHeader(): FileSystemHeaderState {
  const state = useFileSystem()

  return createFileSystemHeaderState({
    browser: state.browser,
    title: state.title,
  })
}

export function useFileSystemBrowser(): FileSystemBrowserPartState {
  const state = useFileSystem()

  return createFileSystemBrowserController({
    browser: state.browser,
    openPreview: state.openPreview.open,
    resolveFileSource: state.selection.resolveSource,
  })
}

export function useFileSystemSelection(): FileSystemSelectionState {
  const state = useFileSystem()

  return {
    ...state.selection,
    renderFileActions: state.renderers.renderFileActions,
    renderMetadata: state.renderers.renderMetadata,
  }
}

export function useFileSystemSelectedItem(): FileSystemEntry | null {
  return useFileSystemSelection().entry
}

export function useFileSystemSelectedSource(): FileSystemSelectionSourceTask {
  const selection = useFileSystemSelection()
  const file = selection.entry?.kind === "file" ? selection.entry : null

  return useFileSystemSelectionSourceTask(file, selection.resolveSource)
}

export function FileSystemHeader() {
  const header = useFileSystemHeader()

  return (
    <>
      <FileSystemToolbar {...header} />
      <FileSystemCommandBar controller={header} />
    </>
  )
}

export function FileSystemBrowser() {
  const controller = useFileSystemBrowser()
  const { view } = controller.browser

  return (
    <div className="flex size-full min-h-0 flex-col">
      <div className="min-h-0 flex-1">
        {view === "list" ? (
          <FileSystemListView controller={controller} />
        ) : view === "grid" ? (
          <FileSystemGridView controller={controller} />
        ) : (
          <FileSystemColumnsView controller={controller} />
        )}
      </div>
      <FileSystemStatusBar browser={controller.browser} />
    </div>
  )
}

export function FileSystemSelection({
  children,
}: {
  children: (state: FileSystemSelectionRenderState) => React.ReactNode
}) {
  const selection = useFileSystemSelection()
  const file = selection.entry?.kind === "file" ? selection.entry : null
  const sourceState = useFileSystemSelectionSourceTask(
    file,
    selection.resolveSource
  )

  return (
    <>
      {children({
        ...selection,
        file,
        retry: sourceState.retry,
        source: sourceState.source,
        sourceState,
      })}
    </>
  )
}

"use client"

import type { FileSystemBrowserState } from "./file-system-browser-state"
import type { FileSystemSourceController } from "./file-system-source-controller"
import type { FileSystemFileEntry } from "./file-system-types"

export type FileSystemOpenPreviewCommand = (
  file: FileSystemFileEntry
) => void

export type FileSystemFileActionController = {
  openPreview: FileSystemOpenPreviewCommand
  resolveFileSource: FileSystemSourceController["resolveFileSource"]
}

export type FileSystemBrowserController = {
  browser: FileSystemBrowserState
  fileActions: FileSystemFileActionController
}

export function createFileSystemBrowserController({
  browser,
  openPreview,
  resolveFileSource,
}: {
  browser: FileSystemBrowserState
  openPreview: FileSystemOpenPreviewCommand
  resolveFileSource: FileSystemSourceController["resolveFileSource"]
}): FileSystemBrowserController {
  return {
    browser,
    fileActions: {
      openPreview,
      resolveFileSource,
    },
  }
}

"use client"

import {
  buildFileSystemIndex,
  normalizeFilePath,
  normalizeFolderPath,
} from "./file-system-index"
import {
  createFileSystemQueryState,
  DEFAULT_FILE_SYSTEM_QUERY,
  deriveVisibleIndex,
} from "./file-system-query"
import type {
  FileSystemEntry,
  FileSystemFileEntry,
  FileSystemFolderEntry,
  FileSystemIndex,
  FileSystemItem,
  FileSystemQueryState,
  FileSystemSortKey,
  FileSystemView,
} from "./file-system-types"

export type FileSystemHistoryState = {
  back: string[]
  forward: string[]
}

export type FileSystemTreeState = {
  childrenByPath: Map<string, string[]>
  entriesByPath: Map<string, FileSystemEntry>
}

export type FileSystemFolderLoadReason =
  | "navigate"
  | "expand"
  | "retry"
  | "reveal-selection"

export type FileSystemFolderLoadState =
  | { status: "loaded" }
  | { status: "loading"; requestId: string; reason: FileSystemFolderLoadReason }
  | { status: "failed"; error: string }

export type FileSystemFolderLoadStateByPath = Map<
  string,
  FileSystemFolderLoadState
>

export type FileSystemPathChangeSource =
  | "controlled-prop"
  | "history"
  | "reveal"
  | "user"

export type FileSystemEventSource = "controlled-prop" | "user"

export type FileSystemKernelState = {
  folders: FileSystemFolderLoadStateByPath
  history: FileSystemHistoryState
  path: string
  query: FileSystemQueryState
  selectionPath: string | null
  tree: FileSystemTreeState
  view: FileSystemView
}

export type FileSystemKernelEvent =
  | { items: readonly FileSystemItem[]; type: "items.replaced" }
  | { type: "path.changed"; path: string; source: FileSystemPathChangeSource }
  | { type: "history.back" }
  | { type: "history.forward" }
  | {
      type: "query.changed"
      query: FileSystemQueryState
      source: FileSystemEventSource
    }
  | { type: "query.searchChanged"; search: string }
  | { type: "query.sortKeyChanged"; key: FileSystemSortKey }
  | { type: "view.changed"; source: FileSystemEventSource; view: FileSystemView }
  | { path: string | null; source: FileSystemEventSource; type: "entry.selected" }
  | { path: string; type: "entry.openRequested" }
  | {
      path: string
      reason: FileSystemFolderLoadReason
      requestId: string
      type: "folder.loadRequested"
    }
  | {
      items: FileSystemItem[]
      path: string
      requestId: string
      type: "folder.loadSucceeded"
    }
  | {
      error: string
      path: string
      requestId: string
      type: "folder.loadFailed"
    }

export type FileSystemKernelCommand =
  | {
      path: string
      reason: FileSystemFolderLoadReason
      requestId: string
      type: "folder.ensure"
    }
  | { path: string; type: "callback.pathChanged" }
  | { query: FileSystemQueryState; type: "callback.queryChanged" }
  | { view: FileSystemView; type: "callback.viewChanged" }
  | { entry: FileSystemEntry | null; type: "callback.selectionChanged" }
  | { file: FileSystemFileEntry; type: "file.open" }

export type FileSystemKernelResult = {
  commands: FileSystemKernelCommand[]
  state: FileSystemKernelState
}

export function createFileSystemKernelState({
  defaultPath = "",
  defaultQuery,
  defaultSelectedPath = null,
  defaultView = "list",
  items,
}: {
  defaultPath?: string
  defaultQuery?: Partial<FileSystemQueryState>
  defaultSelectedPath?: string | null
  defaultView?: FileSystemView
  items: readonly FileSystemItem[]
}): FileSystemKernelState {
  const tree = createFileSystemTreeState(items)
  const requestedPath = normalizeFolderPath(defaultPath)
  const path = isKnownFolderPath(tree, requestedPath) ? requestedPath : ""
  const selectionPath = normalizeSelectionPath(tree, defaultSelectedPath)

  return {
    folders: new Map(),
    history: { back: [], forward: [] },
    path,
    query: createFileSystemQueryState(defaultQuery),
    selectionPath,
    tree,
    view: defaultView,
  }
}

export function reduceFileSystemKernel(
  state: FileSystemKernelState,
  event: FileSystemKernelEvent
): FileSystemKernelResult {
  switch (event.type) {
    case "items.replaced":
      return reduceItemsReplaced(state, event.items)
    case "path.changed":
      return reducePathChanged(state, event)
    case "history.back":
      return reduceHistoryBack(state)
    case "history.forward":
      return reduceHistoryForward(state)
    case "query.changed":
      return reduceQueryChanged(state, event.query, event.source)
    case "query.searchChanged":
      return reduceQueryChanged(
        state,
        { ...state.query, search: event.search },
        "user"
      )
    case "query.sortKeyChanged":
      return reduceQueryChanged(
        state,
        { ...state.query, sort: nextSort(state.query, event.key) },
        "user"
      )
    case "view.changed":
      return reduceViewChanged(state, event.view, event.source)
    case "entry.selected":
      return reduceEntrySelected(state, event.path, event.source)
    case "entry.openRequested":
      return reduceEntryOpenRequested(state, event.path)
    case "folder.loadRequested":
      return reduceFolderLoadRequested(state, event)
    case "folder.loadSucceeded":
      return reduceFolderLoadSucceeded(state, event)
    case "folder.loadFailed":
      return reduceFolderLoadFailed(state, event)
  }
}

function reduceItemsReplaced(
  state: FileSystemKernelState,
  items: readonly FileSystemItem[]
): FileSystemKernelResult {
  const tree = createFileSystemTreeState(items)
  const path = isKnownFolderPath(tree, state.path) ? state.path : ""
  const selectionPath = normalizeSelectionPath(tree, state.selectionPath)

  return {
    commands: [],
    state: {
      ...state,
      folders: new Map(),
      path,
      selectionPath,
      tree,
    },
  }
}

export function createFileSystemTreeState(
  items: readonly FileSystemItem[]
): FileSystemTreeState {
  return fileSystemTreeFromIndex(buildFileSystemIndex(items))
}

export function fileSystemTreeToIndex(
  tree: FileSystemTreeState
): FileSystemIndex {
  const folders = new Map<string, FileSystemFolderEntry>()
  const files = new Map<string, FileSystemFileEntry>()
  const children = new Map<string, FileSystemEntry[]>()

  for (const [path, entry] of tree.entriesByPath) {
    if (entry.kind === "folder") {
      folders.set(path, entry)
    } else {
      files.set(path, entry)
    }
  }

  for (const [parentPath, childPaths] of tree.childrenByPath) {
    const entries = childPaths
      .map((path) => tree.entriesByPath.get(path))
      .filter((entry): entry is FileSystemEntry => Boolean(entry))

    if (entries.length) children.set(parentPath, entries)
  }

  return { children, files, folders }
}

export function mergeFileSystemTreeItems({
  items,
  tree,
}: {
  items: readonly FileSystemItem[]
  tree: FileSystemTreeState
}) {
  return createFileSystemTreeState([...tree.entriesByPath.values(), ...items])
}

export function normalizeFileSystemEntryPath(
  path: string | null | undefined
) {
  if (!path) return null

  return path.endsWith("/") ? normalizeFolderPath(path) : normalizeFilePath(path)
}

function fileSystemTreeFromIndex(index: FileSystemIndex): FileSystemTreeState {
  const entriesByPath = new Map<string, FileSystemEntry>()
  const childrenByPath = new Map<string, string[]>()

  for (const [path, folder] of index.folders) entriesByPath.set(path, folder)
  for (const [path, file] of index.files) entriesByPath.set(path, file)
  for (const [path, children] of index.children) {
    childrenByPath.set(
      path,
      children.map((entry) => entry.path)
    )
  }

  return { childrenByPath, entriesByPath }
}

function reducePathChanged(
  state: FileSystemKernelState,
  event: Extract<FileSystemKernelEvent, { type: "path.changed" }>
): FileSystemKernelResult {
  const path = normalizeFolderPath(event.path)
  const nextPath = isKnownFolderPath(state.tree, path) ? path : ""

  if (nextPath === state.path) return unchanged(state)

  const nextState: FileSystemKernelState = {
    ...state,
    history:
      event.source === "user"
        ? { back: [...state.history.back, state.path], forward: [] }
        : state.history,
    path: nextPath,
    query:
      event.source === "user" || event.source === "history"
        ? { ...state.query, search: "" }
        : state.query,
    selectionPath: null,
  }
  const commands: FileSystemKernelCommand[] =
    event.source === "controlled-prop"
      ? []
      : [
          { path: nextPath, type: "callback.pathChanged" },
          { entry: null, type: "callback.selectionChanged" },
        ]

  return { commands, state: nextState }
}

function reduceHistoryBack(
  state: FileSystemKernelState
): FileSystemKernelResult {
  const path = state.history.back.at(-1)
  if (path === undefined) return unchanged(state)

  return {
    commands: [
      { path, type: "callback.pathChanged" },
      { entry: null, type: "callback.selectionChanged" },
    ],
    state: {
      ...state,
      history: {
        back: state.history.back.slice(0, -1),
        forward: [state.path, ...state.history.forward],
      },
      path,
      query: { ...state.query, search: "" },
      selectionPath: null,
    },
  }
}

function reduceHistoryForward(
  state: FileSystemKernelState
): FileSystemKernelResult {
  const path = state.history.forward[0]
  if (path === undefined) return unchanged(state)

  return {
    commands: [
      { path, type: "callback.pathChanged" },
      { entry: null, type: "callback.selectionChanged" },
    ],
    state: {
      ...state,
      history: {
        back: [...state.history.back, state.path],
        forward: state.history.forward.slice(1),
      },
      path,
      query: { ...state.query, search: "" },
      selectionPath: null,
    },
  }
}

function reduceQueryChanged(
  state: FileSystemKernelState,
  query: FileSystemQueryState,
  source: FileSystemEventSource
): FileSystemKernelResult {
  const nextSelectionPath = selectionMatchesQuery(state, query)
    ? state.selectionPath
    : null
  const commands: FileSystemKernelCommand[] = []

  if (source === "user") commands.push({ query, type: "callback.queryChanged" })
  if (nextSelectionPath !== state.selectionPath) {
    commands.push({ entry: null, type: "callback.selectionChanged" })
  }

  return {
    commands,
    state: { ...state, query, selectionPath: nextSelectionPath },
  }
}

function reduceViewChanged(
  state: FileSystemKernelState,
  view: FileSystemView,
  source: FileSystemEventSource
): FileSystemKernelResult {
  if (view === state.view) return unchanged(state)

  return {
    commands: source === "user" ? [{ type: "callback.viewChanged", view }] : [],
    state: { ...state, view },
  }
}

function reduceEntrySelected(
  state: FileSystemKernelState,
  path: string | null,
  source: FileSystemEventSource
): FileSystemKernelResult {
  const selectionPath = normalizeSelectionPath(state.tree, path)
  if (selectionPath === state.selectionPath) return unchanged(state)

  return {
    commands:
      source === "user"
        ? [
            {
              entry: selectionPath
                ? (state.tree.entriesByPath.get(selectionPath) ?? null)
                : null,
              type: "callback.selectionChanged",
            },
          ]
        : [],
    state: { ...state, selectionPath },
  }
}

function reduceEntryOpenRequested(
  state: FileSystemKernelState,
  path: string
): FileSystemKernelResult {
  const entry = state.tree.entriesByPath.get(normalizeFileSystemEntryPath(path) ?? "")

  if (!entry || entry.kind !== "file") return unchanged(state)
  return { commands: [{ file: entry, type: "file.open" }], state }
}

function reduceFolderLoadRequested(
  state: FileSystemKernelState,
  event: Extract<FileSystemKernelEvent, { type: "folder.loadRequested" }>
): FileSystemKernelResult {
  const path = normalizeFolderPath(event.path)

  return {
    commands: [
      {
        path,
        reason: event.reason,
        requestId: event.requestId,
        type: "folder.ensure",
      },
    ],
    state: {
      ...state,
      folders: new Map(state.folders).set(path, {
        reason: event.reason,
        requestId: event.requestId,
        status: "loading",
      }),
    },
  }
}

function reduceFolderLoadSucceeded(
  state: FileSystemKernelState,
  event: Extract<FileSystemKernelEvent, { type: "folder.loadSucceeded" }>
): FileSystemKernelResult {
  const path = normalizeFolderPath(event.path)
  const current = state.folders.get(path)

  if (
    current?.status !== "loading" ||
    current.requestId !== event.requestId
  ) {
    return unchanged(state)
  }

  const folders = new Map(state.folders)
  folders.set(path, { status: "loaded" })
  const tree = mergeFileSystemTreeItems({ items: event.items, tree: state.tree })

  return {
    commands: [],
    state: {
      ...state,
      folders,
      selectionPath: normalizeSelectionPath(tree, state.selectionPath),
      tree,
    },
  }
}

function reduceFolderLoadFailed(
  state: FileSystemKernelState,
  event: Extract<FileSystemKernelEvent, { type: "folder.loadFailed" }>
): FileSystemKernelResult {
  const path = normalizeFolderPath(event.path)
  const current = state.folders.get(path)

  if (
    current?.status !== "loading" ||
    current.requestId !== event.requestId
  ) {
    return unchanged(state)
  }

  return {
    commands: [],
    state: {
      ...state,
      folders: new Map(state.folders).set(path, {
        error: event.error,
        status: "failed",
      }),
    },
  }
}

function unchanged(state: FileSystemKernelState): FileSystemKernelResult {
  return { commands: [], state }
}

function isKnownFolderPath(tree: FileSystemTreeState, path: string) {
  return path === "" || tree.entriesByPath.get(path)?.kind === "folder"
}

function normalizeSelectionPath(
  tree: FileSystemTreeState,
  path: string | null | undefined
) {
  const entryPath = normalizeFileSystemEntryPath(path)

  return entryPath && tree.entriesByPath.has(entryPath) ? entryPath : null
}

function selectionMatchesQuery(
  state: FileSystemKernelState,
  query: FileSystemQueryState
) {
  if (!state.selectionPath || !query.search) return true

  const rawIndex = fileSystemTreeToIndex(state.tree)
  const visibleIndex = buildVisibleIndex(rawIndex, state.path, query)

  return (
    visibleIndex.files.has(state.selectionPath) ||
    visibleIndex.folders.has(normalizeFolderPath(state.selectionPath))
  )
}

function buildVisibleIndex(
  index: FileSystemIndex,
  path: string,
  query: FileSystemQueryState
) {
  return deriveVisibleIndex(index, path, query)
}

function nextSort(query: FileSystemQueryState, key: FileSystemSortKey) {
  const defaultSort = DEFAULT_FILE_SYSTEM_QUERY.sort

  if (query.sort.key === key) {
    return {
      direction: query.sort.direction === "asc" ? "desc" : "asc",
      key,
    } satisfies FileSystemQueryState["sort"]
  }

  return {
    direction:
      key === defaultSort.key || key === "kind" ? defaultSort.direction : "desc",
    key,
  } satisfies FileSystemQueryState["sort"]
}

"use client"

import * as React from "react"

import { useFileSystemControlledProps } from "./file-system-controlled-props"
import { useFileSystemFolderTask } from "./file-system-folder-task"
import {
  createFileSystemKernelState,
  reduceFileSystemKernel,
  type FileSystemKernelCommand,
  type FileSystemKernelEvent,
  type FileSystemKernelResult,
  type FileSystemKernelState,
} from "./file-system-kernel"
import { useFileSystemKernelCommandEffects } from "./file-system-kernel-command-effects"
import type {
  FileSystemDispatch,
  FileSystemEnsureChildren,
} from "./file-system-kernel-selectors"
import type { FileSystemFileEntry, FileSystemProps } from "./file-system-types"

type FileSystemKernelRuntimeStore = {
  consumeCommands: () => FileSystemKernelCommand[]
  dispatch: (event: FileSystemKernelEvent) => FileSystemKernelResult
  getState: () => FileSystemKernelState
  subscribe: (listener: () => void) => () => void
}

export type FileSystemKernelRuntime = {
  dispatch: FileSystemDispatch
  ensureChildren: FileSystemEnsureChildren
  getState: () => FileSystemKernelState
  state: FileSystemKernelState
}

export function useFileSystemKernelRuntime({
  defaultPath,
  defaultQuery,
  defaultSelectedPath,
  defaultView = "list",
  items,
  loadChildren,
  onFileCommand,
  onPathChange,
  onQueryChange,
  onSelectionChange,
  onViewChange,
  path,
  query,
  selectedPath,
  view,
}: Pick<
  FileSystemProps,
  | "defaultPath"
  | "defaultQuery"
  | "defaultSelectedPath"
  | "defaultView"
  | "items"
  | "loadChildren"
  | "onPathChange"
  | "onQueryChange"
  | "onSelectionChange"
  | "onViewChange"
  | "path"
  | "query"
  | "selectedPath"
  | "view"
> & {
  onFileCommand: (file: FileSystemFileEntry) => void
}): FileSystemKernelRuntime {
  const [commandFlushVersion, setCommandFlushVersion] = React.useState(0)
  const storeRef = React.useRef<FileSystemKernelRuntimeStore | null>(null)

  if (!storeRef.current) {
    storeRef.current = createFileSystemKernelRuntimeStore({
      initialState: createFileSystemKernelState({
        defaultPath,
        defaultQuery,
        defaultSelectedPath,
        defaultView,
        items,
      }),
      scheduleCommandFlush: () => {
        setCommandFlushVersion((version) => version + 1)
      },
    })
  }

  const store = storeRef.current
  const state = React.useSyncExternalStore(
    store.subscribe,
    store.getState,
    store.getState
  )
  const dispatch = React.useCallback<FileSystemDispatch>(
    (event) => {
      store.dispatch(event)
    },
    [store]
  )
  const getState = React.useCallback(() => store.getState(), [store])

  React.useEffect(() => {
    dispatch({ items, type: "items.replaced" })
  }, [dispatch, items])

  useFileSystemControlledProps({
    dispatch,
    path,
    query,
    selectedPath,
    view,
  })

  const folderTask = useFileSystemFolderTask({
    dispatch,
    getState,
    loadChildren,
  })

  React.useEffect(() => {
    void folderTask.ensureChildren(state.path).catch(() => {})
  }, [folderTask, state.path])

  const callbacks = React.useMemo(
    () => ({
      onFileCommand,
      onPathChange,
      onQueryChange,
      onSelectionChange,
      onViewChange,
    }),
    [
      onFileCommand,
      onPathChange,
      onQueryChange,
      onSelectionChange,
      onViewChange,
    ]
  )

  useFileSystemKernelCommandEffects({
    callbacks,
    consumeCommands: store.consumeCommands,
    flushVersion: commandFlushVersion,
    folderTask,
  })

  return React.useMemo(
    () => ({
      dispatch,
      ensureChildren: folderTask.ensureChildren,
      getState,
      state,
    }),
    [dispatch, folderTask.ensureChildren, getState, state]
  )
}

function createFileSystemKernelRuntimeStore({
  initialState,
  scheduleCommandFlush,
}: {
  initialState: FileSystemKernelState
  scheduleCommandFlush: () => void
}): FileSystemKernelRuntimeStore {
  const listeners = new Set<() => void>()
  let commandQueue: FileSystemKernelCommand[] = []
  let state = initialState

  return {
    consumeCommands: () => {
      const commands = commandQueue

      commandQueue = []
      return commands
    },
    dispatch: (event) => {
      const result = reduceFileSystemKernel(state, event)

      if (result.state !== state) {
        state = result.state
        for (const listener of listeners) listener()
      }

      if (result.commands.length) {
        commandQueue = [...commandQueue, ...result.commands]
        scheduleCommandFlush()
      }

      return result
    },
    getState: () => state,
    subscribe: (listener) => {
      listeners.add(listener)
      return () => {
        listeners.delete(listener)
      }
    },
  }
}

"use client"

import * as React from "react"

import type { FileSystemFolderTask } from "./file-system-folder-task"
import type { FileSystemKernelCommand } from "./file-system-kernel"
import type { FileSystemFileEntry, FileSystemProps } from "./file-system-types"

export type FileSystemKernelCallbacks = {
  onFileCommand: (file: FileSystemFileEntry) => void
  onPathChange: FileSystemProps["onPathChange"]
  onQueryChange: FileSystemProps["onQueryChange"]
  onSelectionChange: FileSystemProps["onSelectionChange"]
  onViewChange: FileSystemProps["onViewChange"]
}

export function useFileSystemKernelCommandEffects({
  callbacks,
  consumeCommands,
  flushVersion,
  folderTask,
}: {
  callbacks: FileSystemKernelCallbacks
  consumeCommands: () => FileSystemKernelCommand[]
  flushVersion: number
  folderTask: FileSystemFolderTask
}) {
  React.useEffect(() => {
    const commands = consumeCommands()

    if (!commands.length) return

    for (const command of commands) {
      switch (command.type) {
        case "callback.pathChanged":
          callbacks.onPathChange?.(command.path)
          break
        case "callback.queryChanged":
          callbacks.onQueryChange?.(command.query)
          break
        case "callback.viewChanged":
          callbacks.onViewChange?.(command.view)
          break
        case "callback.selectionChanged":
          callbacks.onSelectionChange?.(command.entry)
          break
        case "file.open":
          callbacks.onFileCommand(command.file)
          break
        case "folder.ensure":
          folderTask.runFolderCommand(command)
          break
      }
    }
  }, [callbacks, consumeCommands, flushVersion, folderTask])
}

"use client"

export type FileSystemAsyncTaskId = string

export type FileSystemAsyncTaskKey = string

export type FileSystemAsyncTask<TInput> = {
  abortController: AbortController
  id: FileSystemAsyncTaskId
  input: TInput
  key: FileSystemAsyncTaskKey
}

export type FileSystemAsyncTaskWaiter<TResult> = {
  reject: (error: unknown) => void
  resolve: (result: TResult) => void
}

export type FileSystemAsyncTaskStart<TInput, TResult> = {
  promise: Promise<TResult>
  started: boolean
  task: FileSystemAsyncTask<TInput>
}

export type FileSystemAsyncTaskRuntime<TInput, TResult> = {
  abort: (key: FileSystemAsyncTaskKey, reason: string) => void
  abortAll: (reason: string) => void
  fail: (task: FileSystemAsyncTask<TInput>, error: unknown) => boolean
  get: (key: FileSystemAsyncTaskKey) => FileSystemAsyncTask<TInput> | null
  join: (task: FileSystemAsyncTask<TInput>) => Promise<TResult>
  start: (input: TInput) => FileSystemAsyncTaskStart<TInput, TResult>
  succeed: (task: FileSystemAsyncTask<TInput>, result: TResult) => boolean
}

export function createFileSystemAsyncTaskRuntime<TInput, TResult>({
  createTaskId = createDefaultTaskId,
  keyForInput,
}: {
  createTaskId?: () => FileSystemAsyncTaskId
  keyForInput: (input: TInput) => FileSystemAsyncTaskKey
}): FileSystemAsyncTaskRuntime<TInput, TResult> {
  const tasksByKey = new Map<
    FileSystemAsyncTaskKey,
    FileSystemAsyncTask<TInput>
  >()
  const waitersByTaskId = new Map<
    FileSystemAsyncTaskId,
    FileSystemAsyncTaskWaiter<TResult>[]
  >()

  function join(task: FileSystemAsyncTask<TInput>) {
    const promise = new Promise<TResult>((resolve, reject) => {
      const currentTask = tasksByKey.get(task.key)

      if (currentTask?.id !== task.id) {
        reject(createStaleTaskError(task))
        return
      }

      const waiters = waitersByTaskId.get(task.id) ?? []
      waiters.push({ reject, resolve })
      waitersByTaskId.set(task.id, waiters)
    })

    void promise.catch(() => {})
    return promise
  }

  function start(input: TInput): FileSystemAsyncTaskStart<TInput, TResult> {
    const key = keyForInput(input)
    const currentTask = tasksByKey.get(key)

    if (currentTask) {
      return {
        promise: join(currentTask),
        started: false,
        task: currentTask,
      }
    }

    const task = {
      abortController: new AbortController(),
      id: createTaskId(),
      input,
      key,
    }

    tasksByKey.set(key, task)

    return {
      promise: join(task),
      started: true,
      task,
    }
  }

  function succeed(task: FileSystemAsyncTask<TInput>, result: TResult) {
    return settle(task, (waiter) => waiter.resolve(result))
  }

  function fail(task: FileSystemAsyncTask<TInput>, error: unknown) {
    return settle(task, (waiter) => waiter.reject(error))
  }

  function abort(key: FileSystemAsyncTaskKey, reason: string) {
    const task = tasksByKey.get(key)

    if (!task) return

    task.abortController.abort()
    fail(task, createAbortTaskError(task, reason))
  }

  function abortAll(reason: string) {
    for (const key of [...tasksByKey.keys()]) {
      abort(key, reason)
    }
  }

  function settle(
    task: FileSystemAsyncTask<TInput>,
    settleWaiter: (waiter: FileSystemAsyncTaskWaiter<TResult>) => void
  ) {
    const currentTask = tasksByKey.get(task.key)

    if (currentTask?.id !== task.id) return false

    const waiters = waitersByTaskId.get(task.id) ?? []
    tasksByKey.delete(task.key)
    waitersByTaskId.delete(task.id)

    for (const waiter of waiters) settleWaiter(waiter)

    return true
  }

  function get(key: FileSystemAsyncTaskKey) {
    return tasksByKey.get(key) ?? null
  }

  return { abort, abortAll, fail, get, join, start, succeed }
}

function createDefaultTaskId() {
  return `task:${Math.random().toString(36).slice(2)}`
}

function createStaleTaskError<TInput>(task: FileSystemAsyncTask<TInput>) {
  return new Error(`Stale async task: ${task.id}`)
}

function createAbortTaskError<TInput>(
  task: FileSystemAsyncTask<TInput>,
  reason: string
) {
  return new Error(`Aborted async task ${task.id}: ${reason}`)
}

"use client"

import * as React from "react"

import { normalizeFolderPath } from "./file-system-index"
import type {
  FileSystemKernelCommand,
  FileSystemKernelState,
} from "./file-system-kernel"
import {
  selectFileSystemKernel,
  type FileSystemDispatch,
  type FileSystemEnsureChildren,
} from "./file-system-kernel-selectors"
import type {
  FileSystemEntry,
  FileSystemItem,
  FileSystemProps,
} from "./file-system-types"

export type FileSystemFolderTask = {
  abortAll: () => void
  ensureChildren: FileSystemEnsureChildren
  runFolderCommand: (
    command: Extract<FileSystemKernelCommand, { type: "folder.ensure" }>
  ) => void
}

type FolderLoadRequest = {
  abortController: AbortController
  path: string
  requestId: string
  status: "queued" | "loading"
}

type FolderLoadWaiter = {
  reject: (error: unknown) => void
  resolve: (children: FileSystemEntry[]) => void
}

export function useFileSystemFolderTask({
  dispatch,
  getState,
  loadChildren,
}: {
  dispatch: FileSystemDispatch
  getState: () => FileSystemKernelState
  loadChildren: FileSystemProps["loadChildren"]
}): FileSystemFolderTask {
  const nextRequestNumberRef = React.useRef(0)
  const requestsByPathRef = React.useRef(new Map<string, FolderLoadRequest>())
  const waitersByRequestIdRef = React.useRef(
    new Map<string, FolderLoadWaiter[]>()
  )
  const selectVisibleChildren = React.useCallback(
    (path: string) =>
      selectFileSystemKernel({ state: getState() }).index.children.get(path) ??
      [],
    [getState]
  )

  const joinRequest = React.useCallback((request: FolderLoadRequest) => {
    const promise = new Promise<FileSystemEntry[]>((resolve, reject) => {
      if (!isCurrentFolderRequest(requestsByPathRef.current, request)) {
        reject(createStaleFolderRequestError(request))
        return
      }

      const waiters = waitersByRequestIdRef.current.get(request.requestId) ?? []
      waiters.push({ reject, resolve })
      waitersByRequestIdRef.current.set(request.requestId, waiters)
    })

    void promise.catch(() => {})
    return promise
  }, [])

  const createRequest = React.useCallback((path: string) => {
    const request: FolderLoadRequest = {
      abortController: new AbortController(),
      path,
      requestId: `folder:${++nextRequestNumberRef.current}`,
      status: "queued",
    }

    requestsByPathRef.current.set(path, request)
    return request
  }, [])

  const settleRequest = React.useCallback(
    (
      request: FolderLoadRequest,
      settleWaiter: (waiter: FolderLoadWaiter) => void
    ) => {
      if (!isCurrentFolderRequest(requestsByPathRef.current, request)) {
        return false
      }

      const waiters =
        waitersByRequestIdRef.current.get(request.requestId) ?? []
      requestsByPathRef.current.delete(request.path)
      waitersByRequestIdRef.current.delete(request.requestId)

      for (const waiter of waiters) settleWaiter(waiter)
      return true
    },
    []
  )

  const failRequest = React.useCallback(
    (request: FolderLoadRequest, error: unknown) => {
      settleRequest(request, (waiter) => waiter.reject(error))
    },
    [settleRequest]
  )

  const settleRequestFromCommittedChildren = React.useCallback(
    (request: FolderLoadRequest) => {
      const children = selectVisibleChildren(request.path)

      settleRequest(request, (waiter) => waiter.resolve(children))
    },
    [selectVisibleChildren, settleRequest]
  )

  const abortRequest = React.useCallback(
    (path: string, reason: string) => {
      const request = requestsByPathRef.current.get(path)

      if (!request) return

      request.abortController.abort()
      failRequest(request, createAbortFolderRequestError(request, reason))
    },
    [failRequest]
  )

  const ensureChildren = React.useCallback<FileSystemEnsureChildren>(
    (path, options = {}) => {
      const folderPath = normalizeFolderPath(path)
      const selectors = selectFileSystemKernel({ state: getState() })
      const folder = selectors.rawIndex.folders.get(folderPath)
      const rawChildren = selectors.rawIndex.children.get(folderPath) ?? []
      const visibleChildren = selectors.index.children.get(folderPath) ?? []

      if (!loadChildren || !folder?.hasChildren) {
        return Promise.resolve(visibleChildren)
      }
      if (!options.retry && rawChildren.length > 0) {
        return Promise.resolve(visibleChildren)
      }
      if (options.retry) {
        abortRequest(folderPath, "retry")
      }

      let request = requestsByPathRef.current.get(folderPath)
      const started = !request

      if (!request) {
        request = createRequest(folderPath)
      }

      const promise = joinRequest(request)

      if (started) {
        dispatch({
          path: folderPath,
          reason: options.retry ? "retry" : "expand",
          requestId: request.requestId,
          type: "folder.loadRequested",
        })
      }

      return promise.catch(() => selectVisibleChildren(folderPath))
    },
    [
      abortRequest,
      createRequest,
      dispatch,
      getState,
      joinRequest,
      loadChildren,
      selectVisibleChildren,
    ]
  )

  const runFolderCommand = React.useCallback<
    FileSystemFolderTask["runFolderCommand"]
  >(
    (command) => {
      const path = normalizeFolderPath(command.path)
      const request = requestsByPathRef.current.get(path)

      if (
        !request ||
        request.requestId !== command.requestId ||
        request.status === "loading"
      ) {
        return
      }

      if (!loadChildren) {
        settleRequestFromCommittedChildren(request)
        return
      }

      request.status = "loading"

      void (async () => {
        try {
          let cursor: string | null = null
          const items: FileSystemItem[] = []

          do {
            const result = await loadChildren({
              cursor,
              path: request.path,
              signal: request.abortController.signal,
            })

            items.push(...result.items)
            cursor = result.nextCursor ?? null
          } while (cursor && !request.abortController.signal.aborted)

          if (request.abortController.signal.aborted) {
            failRequest(request, new Error("Folder request aborted."))
            return
          }

          dispatch({
            items,
            path: request.path,
            requestId: request.requestId,
            type: "folder.loadSucceeded",
          })
          settleRequestFromCommittedChildren(request)
        } catch (error) {
          if (!request.abortController.signal.aborted) {
            dispatch({
              error: errorMessage(error),
              path: request.path,
              requestId: request.requestId,
              type: "folder.loadFailed",
            })
          }
          failRequest(request, error)
        }
      })()
    },
    [dispatch, failRequest, loadChildren, settleRequestFromCommittedChildren]
  )

  const abortAll = React.useCallback(() => {
    for (const path of [...requestsByPathRef.current.keys()]) {
      abortRequest(path, "file-system folder task unmounted")
    }
  }, [abortRequest])

  React.useEffect(() => abortAll, [abortAll])

  return React.useMemo(
    () => ({ abortAll, ensureChildren, runFolderCommand }),
    [abortAll, ensureChildren, runFolderCommand]
  )
}

function errorMessage(error: unknown) {
  return error instanceof Error && error.message
    ? error.message
    : "Unable to load this folder."
}

function isCurrentFolderRequest(
  requestsByPath: Map<string, FolderLoadRequest>,
  request: FolderLoadRequest
) {
  return requestsByPath.get(request.path)?.requestId === request.requestId
}

function createStaleFolderRequestError(request: FolderLoadRequest) {
  return new Error(`Stale folder request: ${request.requestId}`)
}

function createAbortFolderRequestError(
  request: FolderLoadRequest,
  reason: string
) {
  return new Error(`Aborted folder request ${request.requestId}: ${reason}`)
}

"use client"

import * as React from "react"

import type { FileSystemDispatch } from "./file-system-kernel-selectors"
import type {
  FileSystemQueryState,
  FileSystemView,
} from "./file-system-types"

export function useFileSystemControlledProps({
  dispatch,
  path,
  query,
  selectedPath,
  view,
}: {
  dispatch: FileSystemDispatch
  path?: string
  query?: FileSystemQueryState
  selectedPath?: string | null
  view?: FileSystemView
}) {
  React.useEffect(() => {
    if (path !== undefined) {
      dispatch({ path, source: "controlled-prop", type: "path.changed" })
    }
  }, [dispatch, path])

  React.useEffect(() => {
    if (query !== undefined) {
      dispatch({ query, source: "controlled-prop", type: "query.changed" })
    }
  }, [dispatch, query])

  React.useEffect(() => {
    if (view !== undefined) {
      dispatch({ source: "controlled-prop", type: "view.changed", view })
    }
  }, [dispatch, view])

  React.useEffect(() => {
    if (selectedPath !== undefined) {
      dispatch({
        path: selectedPath,
        source: "controlled-prop",
        type: "entry.selected",
      })
    }
  }, [dispatch, selectedPath])
}

