export type FileSystemDispatch = (event: FileSystemKernelEvent) => void

export type FileSystemEnsureChildren = (
  path: string,
  options?: { retry?: boolean }
) => Promise<FileSystemEntry[]>

export type FileSystemKernelSelectors = {
  index: FileSystemIndex
  rawIndex: FileSystemIndex
  selectedEntry: FileSystemEntry | null
  visibleEntries: FileSystemEntry[]
}

export function selectFileSystemKernel({
  state,
}: {
  state: FileSystemKernelState
}): FileSystemKernelSelectors {
  const rawIndex = selectRawIndex(state)
  const index = selectVisibleIndex(state, rawIndex)

  return {
    index,
    rawIndex,
    selectedEntry: selectSelectedEntry(state),
    visibleEntries: index.children.get(state.path) ?? [],
  }
}

function selectRawIndex(state: FileSystemKernelState) {
  const cached = rawIndexCache.get(state.tree)
  if (cached) return cached

  const index = fileSystemTreeToIndex(state.tree)

  rawIndexCache.set(state.tree, index)
  return index
}

function selectVisibleIndex(
  state: FileSystemKernelState,
  rawIndex: FileSystemIndex
) {
  let pathCache = visibleIndexCache.get(state.tree)

  if (!pathCache) {
    pathCache = new Map()
    visibleIndexCache.set(state.tree, pathCache)
  }

  let queryCache = pathCache.get(state.path)

  if (!queryCache) {
    queryCache = new WeakMap()
    pathCache.set(state.path, queryCache)
  }

  const cached = queryCache.get(state.query)
  if (cached) return cached

  const index = deriveVisibleIndex(rawIndex, state.path, state.query)

  queryCache.set(state.query, index)
  return index
}

export function selectSelectedEntry(state: FileSystemKernelState) {
  if (!state.selectionPath) return null

  return state.tree.entriesByPath.get(state.selectionPath) ?? null
}

export function selectFileSystemBrowserState({
  dispatch,
  ensureChildren,
  getState,
  state,
}: {
  dispatch: FileSystemDispatch
  ensureChildren: FileSystemEnsureChildren
  getState: () => FileSystemKernelState
  state: FileSystemKernelState
}): FileSystemBrowserState {
  const selectors = selectFileSystemKernel({ state })

  return {
    canGoBack: state.history.back.length > 0,
    canGoForward: state.history.forward.length > 0,
    currentPath: state.path,
    entries: selectors.visibleEntries,
    ensureChildren,
    folderErrors: selectFolderErrors(state),
    goBack: () => dispatch({ type: "history.back" }),
    goForward: () => dispatch({ type: "history.forward" }),
    index: selectors.index,
    loadingFolders: selectLoadingFolders(state),
    navigateTo: (path) =>
      dispatch({ path, source: "user", type: "path.changed" }),
    query: state.query,
    rawIndex: selectors.rawIndex,
    selectEntry: (entry) =>
      dispatch({
        path: entry?.path ?? null,
        source: "user",
        type: "entry.selected",
      }),
    selectedEntry: selectors.selectedEntry,
    selectedPath: state.selectionPath,
    selectFirstChildAfterEnsure: async (path) => {
      const folderPath = normalizeFolderPath(path)
      const requestedCurrentPath = state.path
      const children = await ensureChildren(path)
      const entry = children[0] ?? null
      const latestState = getState()

      if (latestState.selectionPath !== folderPath) return null
      if (latestState.path !== requestedCurrentPath) return null

      if (entry) {
        dispatch({ path: entry.path, source: "user", type: "entry.selected" })
      }

      return entry
    },
    setSearch: (search) => dispatch({ search, type: "query.searchChanged" }),
    setSortKey: (key) => dispatch({ key, type: "query.sortKeyChanged" }),
    setView: (view: FileSystemView) =>
      dispatch({ source: "user", type: "view.changed", view }),
    view: state.view,
  }
}

export function selectFileSystemHeaderState({
  browser,
  title,
}: {
  browser: FileSystemBrowserState
  title: string
}): FileSystemHeaderState {
  return {
    canGoBack: browser.canGoBack,
    canGoForward: browser.canGoForward,
    currentPath: browser.currentPath,
    goBack: browser.goBack,
    goForward: browser.goForward,
    query: browser.query,
    setSearch: browser.setSearch,
    setSortKey: browser.setSortKey,
    setView: browser.setView,
    title,
    view: browser.view,
  }
}

export function selectFileSystemSelectionState({
  resolveSource,
  state,
}: {
  resolveSource: FileSystemSourceController["resolveFileSource"]
  state: FileSystemKernelState
}): FileSystemSelectionState {
  return {
    entry: selectSelectedEntry(state),
    resolveSource,
  }
}

export function selectFileSystemListInput({
  state,
}: {
  state: FileSystemKernelState
}) {
  const selectors = selectFileSystemKernel({ state })

  return {
    currentPath: state.path,
    folderErrors: selectFolderErrors(state),
    index: selectors.index,
    loadingFolders: selectLoadingFolders(state),
    search: state.query.search,
    selectedPath: state.selectionPath,
  }
}

export function selectFolderErrors(state: FileSystemKernelState) {
  const errors = new Map<string, string>()

  for (const [path, folder] of state.folders) {
    if (folder.status === "failed") errors.set(path, folder.error)
  }

  return errors
}

export function selectLoadingFolders(state: FileSystemKernelState) {
  const folders = new Set<string>()

  for (const [path, folder] of state.folders) {
    if (folder.status === "loading") folders.add(path)
  }

  return folders
}

export function selectFileEntry(
  state: FileSystemKernelState,
  path: string
): FileSystemFileEntry | null {
  const entryPath = normalizeFileSystemEntryPath(path)
  const entry = entryPath ? state.tree.entriesByPath.get(entryPath) : null

  return entry?.kind === "file" ? entry : null
}

"use client"

import * as React from "react"

import type { ViewerSource } from "@/lib/viewer-source"

import { createFileSystemAsyncTaskRuntime } from "./file-system-async-task"
import type { FileSystemFileEntry } from "./file-system-types"

export type FileSystemSourceResolver = (
  file: FileSystemFileEntry,
  signal: AbortSignal
) => Promise<ViewerSource | null>

export type FileSystemSelectionSourceState =
  | { source: ViewerSource | null; status: "idle" }
  | { source: null; status: "loading" }
  | { source: ViewerSource; status: "ready" }
  | { source: null; status: "unavailable" }
  | { error: string; source: null; status: "error" }

export type FileSystemSelectionSourceTask = FileSystemSelectionSourceState & {
  retry: () => void
}

type FileSystemSelectionSourceTaskInput = {
  file: FileSystemFileEntry
  retryKey: number
}

export function useFileSystemSelectionSourceTask(
  file: FileSystemFileEntry | null,
  resolveFileSource?: FileSystemSourceResolver
): FileSystemSelectionSourceTask {
  const [retryKey, setRetryKey] = React.useState(0)
  const [state, setState] = React.useState<FileSystemSelectionSourceState>({
    source: null,
    status: "idle",
  })
  const nextTaskNumberRef = React.useRef(0)
  const taskRuntimeRef = React.useRef(
    createFileSystemAsyncTaskRuntime<
      FileSystemSelectionSourceTaskInput,
      ViewerSource | null
    >({
      createTaskId: () => `preview-source:${++nextTaskNumberRef.current}`,
      keyForInput: (input) =>
        [
          "preview-source",
          input.file.path,
          input.file.key,
          input.retryKey,
        ].join("\0"),
    })
  )
  const retry = React.useCallback(() => setRetryKey((key) => key + 1), [])

  React.useEffect(() => {
    if (!file) {
      setState({ source: null, status: "idle" })
      return
    }
    if (file.source) {
      setState({ source: file.source, status: "ready" })
      return
    }
    if (!resolveFileSource) {
      setState({ source: null, status: "unavailable" })
      return
    }

    const taskRuntime = taskRuntimeRef.current
    const { promise, task } = taskRuntime.start({ file, retryKey })

    setState({ source: null, status: "loading" })
    void resolveFileSource(file, task.abortController.signal)
      .then((source) => taskRuntime.succeed(task, source))
      .catch((error) => taskRuntime.fail(task, error))

    void promise
      .then((source) => {
        if (task.abortController.signal.aborted) return
        setState(
          source
            ? { source, status: "ready" }
            : { source: null, status: "unavailable" }
        )
      })
      .catch((error) => {
        if (task.abortController.signal.aborted) return

        setState({
          error: selectionSourceErrorMessage(error),
          source: null,
          status: "error",
        })
      })

    return () => taskRuntime.abort(task.key, "preview source task superseded")
  }, [file, resolveFileSource, retryKey])

  return { ...state, retry }
}

function selectionSourceErrorMessage(error: unknown) {
  return error instanceof Error && error.message
    ? error.message
    : "Couldn't load this file."
}

"use client"

import * as React from "react"

import type { ViewerSource } from "@/lib/viewer-source"

import { createFileSystemAsyncTaskRuntime } from "./file-system-async-task"
import type { FileSystemSourceController } from "./file-system-source-controller"
import type { FileSystemFileEntry, FileSystemProps } from "./file-system-types"

export type FileSystemOpenSourceState =
  | { status: "idle" }
  | { file: FileSystemFileEntry; status: "resolving" }
  | { file: FileSystemFileEntry; source: ViewerSource; status: "open" }
  | { file: FileSystemFileEntry; status: "unavailable" }
  | { error: string; file: FileSystemFileEntry; status: "failed" }

export type FileSystemOpenSourceTask = {
  close: () => void
  open: (file: FileSystemFileEntry) => void
  state: FileSystemOpenSourceState
}

type FileSystemOpenSourceTaskInput = {
  file: FileSystemFileEntry
}

export function useFileSystemOpenSourceTask({
  onFileOpen,
  resolveFileSource,
}: {
  onFileOpen?: FileSystemProps["onFileOpen"]
  resolveFileSource: FileSystemSourceController["resolveFileSource"]
}): FileSystemOpenSourceTask {
  const [state, setState] = React.useState<FileSystemOpenSourceState>({
    status: "idle",
  })
  const nextTaskNumberRef = React.useRef(0)
  const taskRuntimeRef = React.useRef(
    createFileSystemAsyncTaskRuntime<
      FileSystemOpenSourceTaskInput,
      ViewerSource | null
    >({
      createTaskId: () => `open-source:${++nextTaskNumberRef.current}`,
      keyForInput: () => "open-source",
    })
  )

  const close = React.useCallback(() => {
    taskRuntimeRef.current.abortAll("open source task closed")
    setState({ status: "idle" })
  }, [])

  const open = React.useCallback(
    (file: FileSystemFileEntry) => {
      const taskRuntime = taskRuntimeRef.current

      taskRuntime.abortAll("open source task superseded")
      const { promise, task } = taskRuntime.start({ file })
      setState({ file, status: "resolving" })

      void resolveFileSource(file, task.abortController.signal)
        .then((source) => taskRuntime.succeed(task, source))
        .catch((error) => taskRuntime.fail(task, error))

      void promise
        .then((source) => {
          if (task.abortController.signal.aborted) return

          onFileOpen?.(file, source)
          if (!source) {
            setState({ file, status: "unavailable" })
            return
          }

          setState({ file, source, status: "open" })
        })
        .catch((error: unknown) => {
          if (task.abortController.signal.aborted) return

          onFileOpen?.(file, null)
          setState({
            error: openSourceErrorMessage(error),
            file,
            status: "failed",
          })
        })
    },
    [onFileOpen, resolveFileSource]
  )

  React.useEffect(() => close, [close])

  return React.useMemo(() => ({ close, open, state }), [close, open, state])
}

function openSourceErrorMessage(error: unknown) {
  return error instanceof Error && error.message
    ? error.message
    : "Unable to open file."
}

